<?php require __DIR__ . '/includes/config.php'; $pageTitle='Categories'; $category = $_GET['category'] ?? ''; $categories = $pdo ? $pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll() : []; $query='SELECT p.*, c.name category FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.status="active"'; $params=[]; if ($category) {$query.=' AND c.slug=?';$params[]=$category;} $query.=' ORDER BY p.created_at DESC'; $statement=$pdo? $pdo->prepare($query):null; if($statement){$statement->execute($params);$products=$statement->fetchAll();}else{$products=[];} require __DIR__ . '/includes/header.php'; ?>
<section class="container py-5"><div class="eyebrow">Browse</div><h1 class="display-4 mb-4">Shop by category</h1><div class="d-flex flex-wrap gap-2 mb-5"><a class="btn <?= !$category?'btn-dark':'btn-outline-dark' ?>" href="category.php">All</a><?php foreach($categories as $item): ?><a class="btn <?= $category===$item['slug']?'btn-dark':'btn-outline-dark' ?>" href="?category=<?= e($item['slug']) ?>"><?= e($item['name']) ?></a><?php endforeach; ?></div><div class="row g-4"><?php foreach($products as $product): ?><div class="col-sm-6 col-lg-3"><article class="card product-card"><a href="product.php?id=<?= $product['id'] ?>"><img class="card-img-top product-img" src="<?= e($product['image']) ?>" alt="<?= e($product['name']) ?>"></a><div class="card-body"><div class="tag"><?= e($product['category']) ?></div><h3 class="h5 mt-2"><?= e($product['name']) ?></h3><div class="price">$<?= number_format((float)$product['price'],2) ?></div><form method="post" action="product.php?id=<?= $product['id'] ?>" class="d-grid gap-2 mt-3"><input type="hidden" name="quantity" value="1"><button name="action" value="cart" class="btn btn-dark btn-sm">Add to cart</button><button name="action" value="buy" class="btn btn-accent btn-sm">Buy now</button></form></div></article></div><?php endforeach; ?></div></section><?php require __DIR__ . '/includes/footer.php'; ?>